def long_path(path):
    path = Path(path).resolve()
    if os.name == 'nt' and not str(path).startswith('\\\\?\\'):
        name = str(path)
        path = Path('\\\\?\\UNC\\' + name[2:] if name.startswith('\\\\') else '\\\\?\\' + name)
    return path


def read_text(path):
    return path.read_bytes().decode('utf-8-sig').replace('\r\n', '\n') if path.is_file() else ''


def parse_repo(value):
    value = value.strip().rstrip('/')
    for prefix in ('https://github.com/', 'http://github.com/',
                   'git@github.com:', 'ssh://git@github.com/'):
        if value.startswith(prefix):
            value = value[len(prefix):]
            break
    if value.endswith('.git'):
        value = value[:-4]
    match = re.fullmatch(r'([A-Za-z0-9][A-Za-z0-9-]{0,38})/([A-Za-z0-9_.-]+)', value)
    if not match or match[2] in ('.', '..'):
        raise ValueError('GitHub 저장소 주소를 입력하세요. 예: https://github.com/owner/repo')
    owner, repo = match.groups()
    base = 'https://' + owner.lower() + '.github.io/'
    if repo.lower() != owner.lower() + '.github.io':
        base += repo + '/'
    return f'https://github.com/{owner}/{repo}.git', base


def has_config(root):
    return any((root / name).is_file() for name in CONFIGS) or (root / 'config').is_dir()


def source_digest(root):
    import unicodedata
    records = []
    for directory, dirs, files in os.walk(root):
        dirs[:] = [d for d in dirs if d not in ('.git', 'node_modules', 'public', '__pycache__', BACKUPS)]
        linked_dirs = [name for name in dirs if (Path(directory) / name).is_symlink()]
        dirs[:] = [name for name in dirs if name not in linked_dirs]
        for name in files + linked_dirs:
            if name in ('prepare_github_pages.py', '.DS_Store', STATE):
                continue
            file = Path(directory) / name
            if file.is_symlink():
                data = os.readlink(file).encode('utf-8')
            else:
                data = file.read_bytes()
            rel = '/'.join(part.rstrip(' .') for part in file.relative_to(root).parts)
            records.append((unicodedata.normalize('NFC', rel), hashlib.sha256(data).hexdigest()))
    digest = hashlib.sha256()
    for rel, sha in sorted(records):
        digest.update((rel + '\0' + sha + '\n').encode('utf-8'))
    return digest.hexdigest()


def identify(root):
    # Hash each identifying file once, even when many themes use theme.toml.
    hashes = {}
    def fingerprint(rel):
        if rel not in hashes:
            file = root / rel
            hashes[rel] = hashlib.sha256(file.read_bytes()).hexdigest() if file.is_file() else None
        return hashes[rel]
    for row in CATALOG:
        if all(fingerprint(rel) == sha for rel, sha in row['anchors']):
            return dict(row, exact=True, snapshot_matches=source_digest(root) == row['source_digest'])
    name = re.sub(r'-(main|master|HEAD)$', '', root.name, flags=re.I).lower()
    for row in CATALOG:
        if name in (row['slug'].lower(), row['repo'].rstrip('/').split('/')[-1].lower()):
            return dict(row, exact=False)
    return {'slug': name, 'exact': False, 'version': '0.167.0', 'build': 'unverified'}


def choose_source(root, entry):
    if entry.get('exact') and 'sample' in entry:
        sample = root / entry['sample'] if entry['sample'] is not None else None
        theme = root / entry['theme'] if entry['theme'] is not None else None
        return sample, theme
    if has_config(root) and (root / 'content').is_dir():
        return root, None
    for name in ('exampleSite', 'example-site', 'example', 'demo', 'docs',
                 'website', 'site', 'examples/exampleSite', 'examples/basic'):
        if has_config(root / name):
            return root / name, root
    for name in ('example', 'examples'):
        if (root / name).is_dir():
            for child in sorted((root / name).iterdir()):
                if child.is_dir() and has_config(child):
                    return child, root
    if (root / 'layouts').is_dir() or (root / 'theme.toml').is_file():
        return None, root
    if has_config(root):
        return root, None
    raise ValueError('Hugo 테마/사이트를 찾지 못했습니다. ZIP을 푼 최상위 폴더에서 실행하세요.')


ARCHIVE_LINKS = {'risotto': {'exampleSite/content/_index.md': '../../README.md'}, 'blox-tailwind': {'CLAUDE.md': 'AGENTS.md'}, 'hugo-black-and-light-theme': {'exampleSite/themes/black-and-light': '../..'}, 'hugo-primer-blog': {'exampleSite/themes/hugo-primer-blog': '../..'}, 'hugo-techie-personal': {'exampleSite/themes/hugo-techie-personal': '../../'}, 'hugo-trainsh': {'exampleSite/themes/hugo-trainsh': '../../../hugo-trainsh'}, 'oink': {'tests/site/themes/oink': '../../..'}, 'hugo-simple': {'.claude/skills/agent-browser': '../../.agents/skills/agent-browser'}, 'hextra': {'CLAUDE.md': 'AGENTS.md'}, 'shizuka': {'exampleSite/themes/shizuka': '../../'}, 'indiepaper': {'exampleSite/themes/indiepaper': '../..'}, 'hugo-fortyten': {'exampleSite/themes/fortyten': '../../'}, 'slick': {'_sites/changelog/static/images/screenshot.png': '../../../../images/screenshot.png', '_sites/changelog/static/images/tn.png': '../../../../images/tn.png', '_sites/changelog/themes/slick': '../../../', '_sites/example/themes/slick': '../../../', 'exampleSite': '_sites/example'}, 'bilberry-hugo-theme': {'.github/README.md': '../v4/README.md'}, 'hugo-arcana': {'exampleSite/themes/hugo-arcana': '../../'}, 'tailbliss': {'exampleSite/themes/tailbliss': '..'}, 'gokarna': {'exampleSite/themes/gokarna': '../../'}, 'toph-hugo-theme': {'exampleSite/themes/toph': '../..'}}


def copy_tree(source, dest, root_excludes=(), archive_root=None, archive_links=None, _seen=()):
    """Materialize internal ZIP links and omit recursive local theme links."""
    source = long_path(source)
    dest = long_path(dest)
    boundary = long_path(archive_root or source).resolve()
    links = archive_links or {}
    seen = set(_seen)
    resolved_source = source.resolve()
    if not resolved_source.is_relative_to(boundary):
        raise ValueError(f'ZIP 밖의 폴더를 가리키는 링크입니다: {source}')
    if resolved_source in seen:
        return
    seen.add(resolved_source)
    always = {'.git', '.github', 'node_modules', 'public', '__pycache__', BACKUPS}

    def link_target(src):
        if src.is_symlink():
            target = src.resolve()
        else:
            try:
                rel = src.relative_to(boundary).as_posix()
            except ValueError:
                return None
            value = links.get(rel)
            if value is None or not src.is_file() or src.read_bytes() != value.encode('utf-8'):
                return None
            target = (src.parent / value).resolve()
        if not target.is_relative_to(boundary):
            raise ValueError(f'ZIP 밖의 파일을 가리키는 링크입니다: {src}')
        return target

    for current, dirs, files in os.walk(source, followlinks=False):
        current = Path(current)
        rel = current.relative_to(source)
        dirs[:] = [d for d in dirs if d not in always and
                   not (current == source and d.casefold() in {x.casefold() for x in root_excludes})]
        target_dir = dest.joinpath(*(part.rstrip(' .') for part in rel.parts))
        target_dir.mkdir(parents=True, exist_ok=True)
        for name in list(dirs):
            src = current / name
            if src.is_symlink():
                dirs.remove(name)
                target = link_target(src)
                if target == current.resolve() or target in current.resolve().parents or target in seen:
                    continue
                copy_tree(target, target_dir / name.rstrip(' .'), archive_root=boundary,
                          archive_links=links, _seen=seen)
        for name in files:
            if name in always or name in ('.gitignore', '.gitmodules', '.DS_Store', STATE,
                                           'prepare_github_pages.py', 'go.work', 'go.work.sum'):
                continue
            if current == source and name.casefold() in {x.casefold() for x in root_excludes}:
                continue
            src = current / name
            target = link_target(src)
            if target is not None:
                if target.is_dir():
                    if target == current.resolve() or target in current.resolve().parents or target in seen:
                        continue
                    copy_tree(target, target_dir / name.rstrip(' .'), archive_root=boundary,
                              archive_links=links, _seen=seen)
                    continue
                if not target.is_file():
                    raise ValueError(f'깨진 링크입니다: {src}')
                src = target
            shutil.copy2(src, target_dir / name.rstrip(' .'))


def archive_url(repo):
    repo = repo.rstrip('/').removesuffix('.git')
    if repo.startswith('git@github.com:'):
        repo = 'https://github.com/' + repo.split(':', 1)[1]
    match = re.fullmatch(r'https://github.com/([\w.-]+)/([\w.-]+)', repo)
    if match:
        return f'https://codeload.github.com/{match[1]}/{match[2]}/zip/HEAD'
    match = re.fullmatch(r'https://gitlab.com/([\w./-]+)', repo)
    if match and '..' not in match[1].split('/'):
        return f'https://gitlab.com/{match[1]}/-/archive/HEAD/{match[1].split("/")[-1]}-HEAD.zip'
    raise ValueError('자동 다운로드할 수 없는 의존성 주소: ' + repo)


def download_zip(url, target, expected_sha256=None):
    """Extract regular files only, with bounded size and traversal protection."""
    req = urllib.request.Request(url, headers={'User-Agent': 'Hugo-Pages-Preparation/3.0'})
    context = ssl.create_default_context()
    if sys.platform == 'darwin' and Path('/etc/ssl/cert.pem').is_file():
        context.load_verify_locations('/etc/ssl/cert.pem')
    with urllib.request.urlopen(req, timeout=90, context=context) as response:
        data = response.read(200 * 1024 * 1024 + 1)
    if len(data) > 200 * 1024 * 1024:
        raise ValueError('의존성 ZIP 크기가 200 MB를 초과했습니다.')
    if expected_sha256 and hashlib.sha256(data).hexdigest() != expected_sha256:
        raise ValueError('다운로드한 ZIP의 SHA-256이 검증한 버전과 다릅니다.')
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        infos = archive.infolist()
        if sum(item.file_size for item in infos) > 1024 * 1024 * 1024 or len(infos) > 60000:
            raise ValueError('압축 해제 크기 제한을 초과했습니다.')
        seen = set()
        for item in infos:
            parts = PurePosixPath(item.filename.replace('\\', '/')).parts
            if not parts or parts[0] == '/' or '..' in parts or any(':' in p for p in parts):
                raise ValueError('안전하지 않은 ZIP 경로: ' + item.filename)
            parts = parts[1:]
            if not parts or any(p in ('.git', '.github') for p in parts):
                continue
            if (item.external_attr >> 16) & 0o170000 == 0o120000:
                # GitHub ZIPs can contain symlinks. Never materialize outside links.
                continue
            key = '/'.join(parts).casefold()
            if key in seen and not item.is_dir():
                raise ValueError('Windows에서 충돌하는 ZIP 경로: ' + item.filename)
            seen.add(key)
            dest = target.joinpath(*parts)
            if item.is_dir():
                dest.mkdir(parents=True, exist_ok=True)
            else:
                dest.parent.mkdir(parents=True, exist_ok=True)
                dest.write_bytes(archive.read(item))


def restore_submodules(source, dest, excluded=()):
    import configparser
    file = source / '.gitmodules'
    if not file.is_file():
        return
    parser = configparser.ConfigParser(interpolation=None)
    parser.read_string(read_text(file))
    for section in parser.sections():
        rel = parser.get(section, 'path', fallback='')
        url = parser.get(section, 'url', fallback='')
        parts = PurePosixPath(rel.replace('\\', '/')).parts
        if not parts or '..' in parts or parts[0] == '/' or any(':' in x for x in parts):
            raise ValueError('잘못된 .gitmodules 경로: ' + rel)
        if parts[0].casefold() in {x.casefold() for x in excluded}:
            continue
        target = dest.joinpath(*parts)
        if target.is_dir() and any(target.iterdir()):
            continue
        print('  ZIP 의존성 다운로드:', rel)
        target.mkdir(parents=True, exist_ok=True)
        download_zip(archive_url(url), target)


def stage_site(root, site, entry, base):
    def copy_source(source, destination, excludes=()):
        boundary = sample if entry.get('starter') and source.is_relative_to(sample) else root
        copy_tree(source, destination, excludes, archive_root=boundary,
                  archive_links=ARCHIVE_LINKS.get(entry['slug'], {}))
    root, site = long_path(root), long_path(site)
    sample, theme = choose_source(root, entry)
    if entry.get('starter'):
        sample = site.parent / 'starter-download'
        sample.mkdir(parents=True, exist_ok=True)
        print('  공식 예제 ZIP 다운로드:', entry['slug'])
        download_zip(entry['starter']['url'], sample, entry['starter']['sha256'])
    site.mkdir(parents=True, exist_ok=True)
    if sample:
        copy_source(sample, site, ({'site', 'tmp'} if sample == root else set()) | ({'themes'} if theme else set()))
        restore_submodules(sample, site)
    if theme:
        excluded = {'exampleSite', 'example-site', 'example', 'examples', 'docs', 'demo',
                    'test', 'tests', '.claude', '.watchfire', '.vscode', 'site', 'tmp'}
        copy_source(theme, site / 'themes/template', excluded)
        restore_submodules(theme, site / 'themes/template', excluded)
        if not sample:
            for name in CONFIGS + ('config', 'data', 'content', 'static', 'assets'):
                src = root / name
                if src.is_dir():
                    copy_source(src, site / name)
                elif src.is_file():
                    shutil.copy2(src, site / name)
            for name in ('example-config.toml', 'example-hugo.yaml'):
                if (root / name).is_file():
                    shutil.copy2(root / name, site / ('hugo.toml' if name.endswith('toml') else 'hugo.yaml'))
            if (root / '_example').is_dir():
                copy_source(root / '_example', site / 'content')
        mod = re.search(r'^module\s+(\S+)', read_text(theme / 'go.mod'))
        canonical = entry.get('repo', '').removeprefix('https://').removesuffix('.git')
        if not mod and canonical.startswith('github.com/') and canonical in read_text(site / 'go.mod'):
            (site / 'themes/template/go.mod').write_text('module ' + canonical + '\n\ngo 1.25.0\n', encoding='utf-8')
            mod = re.search(r'^module\s+(\S+)', 'module ' + canonical)
        files = [site / n for n in CONFIGS] + list((site / 'config').rglob('*'))
        theme_dir = site / 'themes/template'
        files += [theme_dir / n for n in CONFIGS] + list((theme_dir / 'config').rglob('*'))
        for file in files:
            if not file.is_file() or file.suffix not in ('.toml', '.yaml', '.yml', '.json'):
                continue
            text = read_text(file)
            if file.suffix == '.json':
                data = json.loads(text)
                data.pop('theme', None)
                data.pop('themesDir', None)
                text = json.dumps(data, ensure_ascii=False, indent=2)
            else:
                text = re.sub(r'(?im)^(?:theme|themesDir)\s*[:=]\s*(?:\[[\s\S]*?\]|[^\r\n]*)', '', text)
            file.write_text(text, encoding='utf-8')
        if mod:
            gomod = site / 'go.mod'
            text = read_text(gomod) or 'module pages.local/site\n\ngo 1.25.0\n'
            if re.search(r'^module\s+' + re.escape(mod[1]) + r'\s*$', text, flags=re.M):
                text = re.sub(r'^module\s+\S+', 'module pages.local/site', text)
            # Preserve local submodules shipped inside a monorepo theme.
            prefix = re.escape(re.sub(r'/v[0-9]+$', '', mod[1]))
            text = re.sub(r'(?m)^([ \t]*' + prefix + r'/[^\s]+\s*=>)\s+\.\./([^\s]+)', lambda m: m[1] + ' ./themes/template/' + m[2], text)
            # Only the selected theme gets a local replacement; retain other dependencies.
            module_pattern = re.escape(re.sub(r'/v[0-9]+$', '', mod[1])) + r'(?:/v[0-9]+)?'
            pattern = r'(?m)^(\s*(?:replace\s+)?' + module_pattern + r'(?:\s+v[^\s]+)?\s*=>)[^\n]*'
            if re.search(pattern, text):
                text = re.sub(pattern, lambda m: m[1] + ' ./themes/template', text)
            else:
                text += '\nreplace ' + mod[1] + ' => ./themes/template\n'
            gomod.write_text(text, encoding='utf-8')
    elif (site / 'layouts').is_dir():
        for file in [site / n for n in CONFIGS] + list((site / 'config').rglob('*')):
            if file.is_file() and file.suffix in ('.toml', '.yaml', '.yml'):
                file.write_text(re.sub(r'(?im)^theme\s*[:=].*$', '', read_text(file)), encoding='utf-8')
    for pattern in ('*postcss*', '*tailwind*', 'package*.json', '.npmrc'):
        for file in root.glob(pattern):
            if file.is_file() and not (site / file.name).exists():
                shutil.copy2(file, site / file.name)
    settings = {'baseURL': base, 'enableGitInfo': False, 'themesDir': 'themes', 'timeout': '120s',
                'security': {'exec': {'allow': ['^(dart-)?sass$', '^go$', '^git$', '^node$',
                                                '^postcss$', '^tailwindcss$', '^asciidoctor$']},
                             'allowContent': ['^text/']}}
    if theme:
        settings['theme'] = ['template']
    if not sample:
        settings['title'] = entry['slug']
    if not any(f.is_file() for f in (site / 'content').rglob('*')) and not any(site.glob('content.*')):
        (site / 'content/posts').mkdir(parents=True, exist_ok=True)
        (site / 'content/_index.md').write_text('---\ntitle: Welcome\n---\nWelcome to my website.\n', encoding='utf-8')
        (site / 'content/posts/hello.md').write_text('---\ntitle: Hello\ndate: 2026-01-01\ndraft: false\n---\nThis is my first post.\n', encoding='utf-8')
    # Only exact, audited ZIP snapshots receive compatibility corrections.
    if entry.get('exact'):
        for src, dst in COPIES.get(entry['slug'], []):
            source = root / src
            target = site / dst
            if source.is_dir():
                copy_source(source, target)
            else:
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(source, target)
        for rel, content in EXTRA_FILES.get(entry['slug'], {}).items():
            file = site / rel
            file.parent.mkdir(parents=True, exist_ok=True)
            file.write_text(content, encoding='utf-8')
        for rel, old, new in PATCHES.get(entry['slug'], []):
            file = site / rel
            if file.is_file():
                text = read_text(file)
                if old not in text:
                    raise ValueError('검증한 테마와 파일 내용이 다릅니다: ' + rel)
                file.write_text(text.replace(old, new), encoding='utf-8')
    (site / 'pages.json').write_text(json.dumps(settings, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    configs = [name for name in CONFIGS if (site / name).is_file()][:1] + ['pages.json']
    return {'config': ','.join(configs), 'theme': 'template' if theme else None,
            'sample': ('official starter ZIP' if entry.get('starter') else str(sample.relative_to(root))) if sample else None,
            'version': entry.get('version', '0.167.0'), 'slug': entry['slug'],
            'npm': entry.get('npm'), 'asset_build': entry.get('asset_build', [])}


def workflow(version):
    if not re.fullmatch(r'0\.\d+\.\d+', version):
        raise ValueError('잘못된 Hugo 버전')
    return '''# Generated by prepare_github_pages.py 3.1
name: Deploy Hugo to GitHub Pages
on:
  push:
    branches: [main]
  workflow_dispatch:
permissions:
  contents: read
  pages: write
  id-token: write
concurrency:
  group: github-pages
  cancel-in-progress: false
jobs:
  build:
    runs-on: ubuntu-latest
    env:
      HUGO_ENVIRONMENT: production
    steps:
      - uses: actions/checkout@v7
      - uses: actions/setup-python@v7
        with:
          python-version: '3.12'
      - uses: actions/setup-node@v7
        with:
          node-version: '24'
      - uses: actions/setup-go@v7
        with:
          go-version: '1.27.1'
          cache: false
      - name: Install Hugo and Sass
        env:
          HUGO_VERSION: 'VERSION_PLACEHOLDER'
        run: |
          set -eu
          mkdir -p "$RUNNER_TEMP/hugo" "$RUNNER_TEMP/sass"
          curl -fL --retry 3 "https://github.com/gohugoio/hugo/releases/download/v${HUGO_VERSION}/hugo_extended_${HUGO_VERSION}_linux-amd64.tar.gz" | tar -xz -C "$RUNNER_TEMP/hugo"
          curl -fL --retry 3 "https://github.com/sass/dart-sass/releases/download/1.105.0/dart-sass-1.105.0-linux-x64.tar.gz" | tar -xz -C "$RUNNER_TEMP/sass"
          echo "$RUNNER_TEMP/hugo" >> "$GITHUB_PATH"
          echo "$RUNNER_TEMP/sass/dart-sass" >> "$GITHUB_PATH"
          echo "HUGO_CACHEDIR=$RUNNER_TEMP/hugo-cache" >> "$GITHUB_ENV"
      - name: Prepare dependencies
        run: python .github/pages_build.py --dependencies
      - uses: actions/configure-pages@v6
        id: pages
      - name: Build and fix project URL paths
        env:
          SITE_BASE_URL: ${{ steps.pages.outputs.base_url }}
        run: python .github/pages_build.py --build
      - uses: actions/upload-pages-artifact@v5
        with:
          path: public
  deploy:
    needs: build
    runs-on: ubuntu-latest
    environment:
      name: github-pages
      url: ${{ steps.deployment.outputs.page_url }}
    steps:
      - uses: actions/deploy-pages@v5
        id: deployment
'''.replace('VERSION_PLACEHOLDER', version)


def prepare(root, repo, base):
    root = long_path(root)
    state_file = root / STATE
    if state_file.exists():
        state = json.loads(read_text(state_file))
        if state.get('generator') != VERSION or not (root / 'site/pages.json').is_file():
            raise ValueError('기존 준비 상태가 다릅니다. 새 ZIP 폴더에서 실행하세요.')
        settings = json.loads(read_text(root / 'site/pages.json'))
        settings['baseURL'] = base
        state.update(repo=repo, baseURL=base)
        (root / 'site/pages.json').write_text(json.dumps(settings, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
        state_file.write_text(json.dumps(state, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
        return state
    entry = identify(root)
    choose_source(root, entry)  # Validate before touching the user's files.
    original_site = (root / 'site').exists() and entry.get('allow_existing_site') and entry.get('snapshot_matches')
    if (root / 'site').exists() and not original_site:
        raise ValueError('site 폴더가 이미 있습니다. 기존 파일 보호를 위해 중단했습니다.')
    if entry.get('exact') and entry.get('build') == 'failed':
        raise ValueError('이 ZIP은 원본 테마의 빌드 문제가 확인되어 자동 배포를 준비할 수 없습니다: ' + entry['slug'] + '\n' + entry.get('reason', ''))
    backup = root / BACKUPS / datetime.now().strftime('%Y%m%d-%H%M%S-%f')
    changes = []
    created = []
    # Build everything in a sibling temporary directory. Network errors cannot damage the project.
    with tempfile.TemporaryDirectory(prefix='hugo-pages-') as tmp:
        stage = Path(tmp) / 'site'
        state = stage_site(root, stage, entry, base)
        state.update(generator=VERSION, repo=repo, baseURL=base,
                     audited=bool(entry.get('snapshot_matches') and entry.get('build') == 'passed'))
        writes = {Path('.github/workflows/hugo-pages.yml'): workflow(state['version']),
                  Path('.github/pages_build.py'): Path(__file__).read_text(encoding='utf-8'),
                  Path(STATE): json.dumps(state, ensure_ascii=False, indent=2) + '\n'}
        ignore = read_text(root / '.gitignore').rstrip() + '\n\n# Prepared Hugo Pages site\n!/site/\n!/site/**\n!/.github/\n!/.github/**\n!/.github-pages.json\n/public/\n/.pages-tools/\n**/node_modules/\n**/resources/_gen/\n**/.hugo_build.lock\n/' + BACKUPS + '/\n'
        writes[Path('.gitignore')] = ignore.lstrip('\n')
        old_workflows = [f for f in (root / '.github/workflows').glob('*') if f.suffix in ('.yml', '.yaml')]
        if (root / '.git').exists():
            conflicts = [f for f in old_workflows if 'deploy-pages@' in read_text(f) and f.name != 'hugo-pages.yml']
            if conflicts:
                raise ValueError('기존 Git 저장소에 배포 워크플로가 있습니다. Download ZIP으로 푼 새 폴더에서 실행하세요.')
            old_workflows = []
        try:
            for rel in set(writes) | {f.relative_to(root) for f in old_workflows}:
                dest = root / rel
                if any(parent.is_symlink() for parent in [dest] + list(dest.parents) if parent != root):
                    raise ValueError('수정 대상 경로에 심볼릭 링크가 있습니다: ' + str(rel))
                if dest.exists():
                    save = backup / rel
                    save.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(dest, save)
                    changes.append(rel)
                else:
                    created.append(rel)
            if original_site:
                backup.mkdir(parents=True, exist_ok=True)
                shutil.move(str(root / 'site'), str(backup / 'original-site'))
            created.append(Path('site'))
            shutil.copytree(stage, root / 'site')
            for old in old_workflows:
                old.unlink()
            for rel, text in writes.items():
                (root / rel).parent.mkdir(parents=True, exist_ok=True)
                (root / rel).write_bytes(text.replace('\r\n', '\n').encode('utf-8'))
        except BaseException:
            for rel in reversed(created):
                dest = root / rel
                if dest.is_dir():
                    shutil.rmtree(dest)
                elif dest.exists():
                    dest.unlink()
            if (backup / 'original-site').exists():
                shutil.move(str(backup / 'original-site'), str(root / 'site'))
            for rel in changes:
                shutil.copy2(backup / rel, root / rel)
            raise
    return state


def run(args, cwd):
    executable = shutil.which(args[0])
    if not executable:
        raise ValueError('빌드 도구를 찾을 수 없습니다: ' + args[0])
    subprocess.run([executable] + args[1:], cwd=cwd, check=True)


def dependencies(root):
    site = root / 'site'
    state = json.loads(read_text(root / STATE))
    folders = [site / rel for rel in state['npm']] if state.get('npm') is not None else [site, site / 'themes/template']
    for folder in folders:
        if (folder / 'package.json').is_file():
            command = 'ci' if (folder / 'package-lock.json').exists() else 'install'
            try:
                run(['npm', command, '--ignore-scripts', '--no-audit', '--no-fund'], folder)
            except subprocess.CalledProcessError:
                run(['npm', 'install', '--ignore-scripts', '--no-audit', '--no-fund', '--legacy-peer-deps'], folder)
    # CLI tools absent from older theme packages are installed in an isolated directory.
    tool_dir = root / '.pages-tools'
    if not all(shutil.which(name) for name in ('postcss', 'tailwindcss', 'pagefind')):
        tool_dir.mkdir(exist_ok=True)
        run(['npm', 'install', '--ignore-scripts', '--no-audit', '--no-fund',
             'postcss-cli@11', 'postcss@8', 'autoprefixer@10', '@tailwindcss/cli@4', 'pagefind@1.5.2'], tool_dir)
    for action in state.get('asset_build', []):
        run(action[1:], site / action[0])
    if not shutil.which('asciidoctor') and (any(site.rglob('*.adoc')) or any(site.rglob('*.asciidoc'))):
        run(['sudo', 'gem', 'install', 'asciidoctor', '--no-document'], root)


def fix_public_paths(public, base):
    """Resolve existing assets under Pages' prefix, then recalculate local SRI."""
    from collections import defaultdict
    from functools import lru_cache
    prefix = urllib.parse.urlsplit(base).path.rstrip('/')
    host = urllib.parse.urlsplit(base).netloc
    files = {p.relative_to(public).as_posix(): p for p in public.rglob('*') if p.is_file()}
    basenames = defaultdict(list)
    for name in files:
        basenames[name.rsplit('/', 1)[-1].casefold()].append(name)

    @lru_cache(maxsize=None)
    def existing(name):
        if name in ('', '/') and 'index.html' in files:
            return 'index.html'
        return name if name in files else (name.rstrip('/') + '/index.html' if name.rstrip('/') + '/index.html' in files else None)

    @lru_cache(maxsize=None)
    def resolve(value, current):
        if not value or value.startswith(('#', '//', 'data:', 'javascript:', 'mailto:', 'tel:')):
            return value, None
        absolute = urllib.parse.urljoin(base.rstrip('/') + '/' + current, html.unescape(value))
        parsed = urllib.parse.urlsplit(absolute)
        if parsed.netloc != host or parsed.scheme not in ('http', 'https'):
            return value, None
        path = urllib.parse.unquote(parsed.path)
        rel = path[len(prefix) + 1:] if prefix and path.startswith(prefix + '/') else path.lstrip('/')
        found = existing(rel)
        # A relative URL which already resolves correctly needs no change.
        if found and (not prefix or path.startswith(prefix + '/')):
            return value, found
        if not found:
            parts = rel.split('/')
            for i in range(1, len(parts)):
                found = existing('/'.join(parts[i:]))
                if found:
                    break
        if not found and Path(rel).suffix.lower() in ('.png', '.jpg', '.jpeg', '.webp', '.gif', '.svg', '.ico', '.css', '.js', '.woff', '.woff2'):
            candidates = basenames.get(rel.rsplit('/', 1)[-1].casefold(), [])
            if len(candidates) == 1:
                found = candidates[0]
        if not found:
            return value, None
        linked = found[:-10] if found.endswith('index.html') and not rel.endswith('index.html') else found
        fixed = prefix + '/' + urllib.parse.quote(linked, safe='/@-._~!$&()*+,;=:')
        if parsed.query:
            fixed += '?' + parsed.query
        if parsed.fragment:
            fixed += '#' + parsed.fragment
        return fixed, found

    attr = re.compile(r'''(\b(?:src|href|poster|data-src)\s*=\s*)("[^"]*"|'[^']*'|[^\s>]+)''', re.I)
    def unquote(value):
        return value[1:-1] if value[:1] in ('"', "'") else value
    changed = 0
    for name, file in files.items():
        if file.suffix not in ('.html', '.css', '.js', '.xml', '.json'):
            continue
        try:
            original = file.read_text(encoding='utf-8')
        except UnicodeDecodeError:
            continue
        text = re.sub(r'''(["'])(/[^\s"'<>]*)\1''', lambda m: m[1] + resolve(m[2], name)[0] + m[1], original)
        text = re.sub(r'url\(\s*(/[^\s)]+)\s*\)', lambda m: 'url(' + resolve(m[1], name)[0] + ')', text)
        if file.suffix == '.html':
            def attribute(match):
                old = html.unescape(unquote(match[2]))
                new = resolve(old, name)[0]
                return match[0] if old == new else match[1] + '"' + html.escape(new, quote=True) + '"'
            # This also handles unquoted attributes emitted by Hugo's minifier.
            text = re.sub(r'<[^>]+>', lambda tag: attr.sub(attribute, tag[0]), text)
            def srcset(match):
                value = re.sub(r'(^|,\s*)([^\s,]+)', lambda m: m[1] + resolve(m[2], name)[0], match[2])
                return match[1] + value + match[3]
            text = re.sub(r'''(\bsrcset=["'])(.*?)(["'])''', srcset, text)
        if text != original:
            file.write_text(text, encoding='utf-8')
            changed += 1

    # Read the final bytes of each referenced asset. Different assets can share an
    # old digest, so replacing hashes globally would be incorrect.
    digest_cache = {}
    attrs = re.compile(r'''\b(src|href|integrity)\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)''', re.I)
    for name, file in files.items():
        if file.suffix != '.html':
            continue
        original = read_text(file)
        def integrity(tag):
            values = {m[1].lower(): html.unescape(unquote(m[2])) for m in attrs.finditer(tag[0])}
            source = values.get('src') or values.get('href')
            if not source or not values.get('integrity'):
                return tag[0]
            _, target = resolve(source, name)
            if not target:
                return tag[0]
            hashes = []
            for item in values['integrity'].split():
                algo = item.split('-', 1)[0]
                if algo not in ('sha256', 'sha384', 'sha512'):
                    continue
                key = (target, algo)
                if key not in digest_cache:
                    digest_cache[key] = algo + '-' + base64.b64encode(hashlib.new(algo, files[target].read_bytes()).digest()).decode()
                hashes.append(digest_cache[key])
            if not hashes:
                return tag[0]
            return re.sub(r'''\bintegrity\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)''', 'integrity="' + ' '.join(hashes) + '"', tag[0], flags=re.I)
        text = re.sub(r'<(?:script|link)\b[^>]*>', integrity, original, flags=re.I)
        if text != original:
            file.write_text(text, encoding='utf-8')
            changed += 1
    return changed


def build(root):
    os.environ.setdefault('GOMAXPROCS', '2')
    state = json.loads(read_text(root / STATE))
    site = root / 'site'
    base = os.environ.get('SITE_BASE_URL') or state['baseURL']
    base = base.rstrip('/') + '/'
    paths = [site / 'node_modules/.bin', site / 'themes/template/node_modules/.bin',
             root / '.pages-tools/node_modules/.bin']
    # Keep the native Dart Sass executable ahead of npm's non-embedded sass CLI.
    os.environ['PATH'] = os.environ.get('PATH', '') + os.pathsep + os.pathsep.join(map(str, paths))
    args = ['hugo', '--gc', '--minify', '--config', state['config'],
            '--destination', '../public', '--baseURL', base, '--enableGitInfo=false']
    if state['theme']:
        args += ['--theme', state['theme'], '--themesDir', str(site / 'themes')]
    run(args, site)
    if not (root / 'public/index.html').is_file():
        raise ValueError('홈페이지 index.html이 생성되지 않아 배포를 중단했습니다.')
    if any(re.search(r'<(?:script|link)[^>]+pagefind/', read_text(file), re.I) for file in (root / 'public').rglob('*.html')):
        run(['pagefind', '--site', str(root / 'public')], root)
    count = fix_public_paths(root / 'public', base)
    (root / 'public/CNAME').unlink(missing_ok=True)
    (root / 'public/.nojekyll').touch()
    print('빌드 완료. 프로젝트 주소 경로 보정:', count, '개 파일')


def main():
    for stream in (sys.stdout, sys.stderr):
        if hasattr(stream, 'reconfigure'):
            stream.reconfigure(encoding='utf-8', errors='backslashreplace')
    try:
        root = Path.cwd()
        if sys.argv[1:] == ['--dependencies']:
            dependencies(root)
        elif sys.argv[1:] == ['--build']:
            build(root)
        elif sys.argv[1:]:
            raise ValueError('인수 없이 실행하세요. 현재 폴더와 main 브랜치를 사용합니다.')
        else:
            print('현재 폴더:', root)
            repo, base = parse_repo(input('GitHub 저장소 주소: '))
            state = prepare(root, repo, base)
            print('\n배포 파일 준비 완료:', root / 'site')
            print('주소:', base, '| 브랜치: main | Hugo:', state['version'])
            if not state['audited']:
                print('주의: 이 ZIP 버전은 전체 빌드 검증 목록과 일치하지 않습니다. Actions 결과를 확인하세요.')
            print('Git 연결·커밋·push는 직접 진행하세요.')
            print('GitHub Settings → Pages → Source를 GitHub Actions로 선택하세요.')
    except (Exception, KeyboardInterrupt) as error:
        print('\n준비/빌드 중단:', str(error) or '취소됨', file=sys.stderr)
        return 1
    return 0


if __name__ == '__main__':
    sys.exit(main())
